use crate::standards::v1::subsets::any::io::sqlite::snapshot::En1994Snapshot;
#[test]
fn sqlite_snapshot_en1994_owned_native_decoder_controls_both_physical_payloads(){
 use store::io::IoPayload;
 let snapshot=fixture();let limits=SqliteDatabaseLimits::default();
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let payload=match encoding{SnapshotEncoding::Binary=>IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};
  let restored=En1994Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(restored,snapshot);
  assert!(En1994Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,limits)).is_err());
  assert!(En1994Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:1,..limits})).is_err());
  assert!(En1994Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:1,..limits})).is_err());
 }
}
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{export_sqlite_database,import_sqlite_database,SnapshotEncoding,SqliteDatabase,SqliteDatabaseLimits,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue}};
fn fixture()->En1994Snapshot{semio_framework_pack_json::from_json_str(include_str!("../🧫️fixtures/🔣️.json"), semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap()}
fn database(snapshot:&En1994Snapshot)->SqliteDatabase{snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn roundtrip(snapshot:&En1994Snapshot)->En1994Snapshot{let bytes=export_sqlite_database(&database(snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();En1994Snapshot::from_sqlite_database(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn set_every_word(s:&mut En1994Snapshot,v:f64){
 s.steel_f_y_pa=v;s.insulation_thickness_m=v;
 for b in &mut s.beams{b.span_m=v;b.spacing_m=v;b.slab_thickness_m=v;b.concrete_f_ck_pa=v;b.concrete_e_cm_pa=v;b.transverse_as_m2_per_m=v;b.ltb_length_m=v;b.as_hogging_m2_per_m=v;b.bar_spacing_m=v;b.wk_limit_m=v;b.n_cycles=v;let x=&mut b.steel;x.height_m=v;x.width_m=v;x.tw_m=v;x.tf_m=v;x.a_m2=v;x.w_pl_y_m3=v;x.i_y_m4=v;x.a_v_m2=v;let x=&mut b.sheeting;x.height_m=v;x.rib_width_m=v;x.thickness_m=v;let x=&mut b.studs;x.diameter_m=v;x.height_m=v;x.f_u_pa=v;x.spacing_m=v;for a in &mut b.actions{a.q_area_pa=v;a.f_k_n=v;a.delta_sigma_k_pa=v;a.delta_tau_k_pa=v;}}
 for c in &mut s.columns{c.length_m=v;c.outer_size_m=v;c.wall_thickness_m=v;c.steel_a_m2=v;c.steel_f_y_pa=v;c.concrete_a_m2=v;c.concrete_f_ck_pa=v;c.reinforcement_as_m2=v;c.reinforcement_f_yk_pa=v;c.i_m4=v;for a in &mut c.actions{a.n_k_n=v;a.m_k_nm=v;}}
 for s in &mut s.slabs{s.span_m=v;s.concrete_thickness_m=v;s.f_ck_pa=v;s.m_factor=v;s.k_factor=v;s.as_m2_per_m=v;s.sheeting.height_m=v;s.sheeting.rib_width_m=v;s.sheeting.thickness_m=v;for a in &mut s.actions{a.q_area_pa=v;a.f_k_n=v;a.delta_sigma_k_pa=v;a.delta_tau_k_pa=v;}}
}
