#[test]
fn sqlite_snapshot_en1994_independent_sqlite_queries_all_components_and_applies_semantic_edits(){
 use std::{io::Write,process::{Command,Stdio}};
 let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const b=db.query('SELECT b.ordinal,a.ordinal AS action,t.count_per_rib,s.ribs_parallel_to_beam FROM en1994_beam b JOIN en1994_beam_steel h ON h.beam_id=b.id JOIN en1994_beam_studs t ON t.beam_id=b.id JOIN en1994_beam_sheeting s ON s.beam_id=b.id JOIN en1994_beam_action a ON a.beam_id=b.id ORDER BY b.ordinal,a.ordinal').all();if(b.length!==2||b[0].ordinal!==0||b[1].action!==1||b[0].count_per_rib!==4294967295||b[0].ribs_parallel_to_beam!==1)throw Error('beam ownership');if(db.query('SELECT c.id FROM en1994_column c JOIN en1994_column_action a ON a.column_id=c.id').all().length!==1||db.query('SELECT s.id FROM en1994_slab s JOIN en1994_slab_sheeting h ON h.slab_id=s.id JOIN en1994_slab_action a ON a.slab_id=s.id').all().length!==1)throw Error('other ownership');const v=Buffer.alloc(8);v.writeDoubleBE(0.625);db.run(\"UPDATE en1994_beam_steel SET designation='Geändert 世界',height_m=0.625,height_m_ieee754_bits=?,height_m_ieee754_class='finite' WHERE id=1\",[BigInt.asIntN(64,v.readBigUInt64BE())]);db.run('UPDATE en1994_beam_studs SET count_per_rib=0,total_count=4294967295');db.run('UPDATE en1994_beam_sheeting SET ribs_parallel_to_beam=0');db.run(\"UPDATE en1994_document SET annex='De'\");await Bun.write(Bun.stdout,db.serialize());db.close();";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));expected.beams[0].steel.designation="Geändert 世界".into();expected.beams[0].steel.height_m=0.625;expected.beams[0].studs.count_per_rib=0;expected.beams[0].studs.total_count=u32::MAX;expected.beams[0].sheeting.ribs_parallel_to_beam=false;expected.annex=crate::document::AnnexChoice::De;assert_eq!(En1994Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
}
