fn sqlite_snapshot_en1994_refuses_malformed_shape_width_boolean_parent_ordinal_word_and_missing_mandatory_entities(){
 let database=database(&fixture());for(table,row,column,value)in[("en1994_document",0,1,SqliteValue::Text("unknown".into())),("en1994_beam_studs",0,5,SqliteValue::Integer(4294967296)),("en1994_beam_studs",0,7,SqliteValue::Integer(-1)),("en1994_beam_sheeting",0,6,SqliteValue::Integer(2)),("en1994_slab_sheeting",0,6,SqliteValue::Integer(-1)),("en1994_beam",0,1,SqliteValue::Integer(99)),("en1994_column",0,2,SqliteValue::Integer(9)),("en1994_slab_action",0,1,SqliteValue::Integer(99)),("en1994_beam_action",1,2,SqliteValue::Integer(0)),("en1994_column_action",0,1,SqliteValue::Integer(99)),("en1994_beam_steel",0,1,SqliteValue::Integer(99)),("en1994_beam_sheeting",0,1,SqliteValue::Integer(99)),("en1994_beam_studs",0,1,SqliteValue::Integer(99)),("en1994_slab_sheeting",0,1,SqliteValue::Integer(99)),("en1994_document",0,8,SqliteValue::Text("nan".into()))]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows[row].values[column]=value;assert!(En1994Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}
 for table in["en1994_document","en1994_beam_steel","en1994_beam_sheeting","en1994_beam_studs","en1994_slab_sheeting"]{let mut invalid=database.clone();invalid.table_mut(table).unwrap().rows.clear();assert!(En1994Snapshot::from_sqlite_database(&invalid,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{table}");}
}
