#[test]
fn sqlite_snapshot_en1994_complete_independent_copied_columns_admission(){
 use store::{ArtifactSqliteSnapshot as _,sqlite_snapshot::*};let source=fixture();let database=source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let limits=SqliteDatabaseLimits{max_columns:38,..SqliteDatabaseLimits::default()};assert!(source.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(En1994Snapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert!(source.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"preflight copied columns {encoding:?}");assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"encoder copied columns {encoding:?}");assert!(En1994Snapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err(),"decoder copied columns {encoding:?}");}
}

#[test]
fn sqlite_snapshot_en1994_borrowed_complete_gate_copied_limits_exact_and_one_short(){
 use store::{ArtifactSqliteSnapshot as _,sqlite_snapshot::*};
 let contract:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎛️semantic.json")).unwrap();let defaults=SqliteDatabaseLimits::default();
 for case in contract["cases"].as_array().unwrap(){let source=norm_complete_source(case);let extent=norm_independent_complete_extent(&source);assert_eq!(extent["rows"],case["rows"]);assert_eq!(extent["valueBytes"],case["valueBytes"]);assert_eq!(extent["schemaBytes"],contract["schemaBytes"]);assert_eq!(extent["tableWidths"],contract["tableWidths"]);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<En1994Snapshot as store::ArtifactPack>::encode_pack_with(&source,&Default::default()).unwrap()),SnapshotEncoding::Text=>store::io::IoPayload::Text(<En1994Snapshot as store::ArtifactDsl>::print_dsl(&source))};
 for(role,total)in[("rows",case["rows"].as_u64().unwrap()as usize),("bytes",case["valueBytes"].as_u64().unwrap()as usize),("schema",contract["schemaBytes"].as_u64().unwrap()as usize),("tables",11),("columns",39)]{for accepted in[true,false]{let maximum=total-usize::from(!accepted);let limits=match role{"rows"=>SqliteDatabaseLimits{max_rows:maximum,..defaults},"bytes"=>SqliteDatabaseLimits{max_value_bytes:maximum,..defaults},"schema"=>SqliteDatabaseLimits{max_schema_bytes:maximum,..defaults},"tables"=>SqliteDatabaseLimits{max_tables:maximum,..defaults},"columns"=>SqliteDatabaseLimits{max_columns:maximum,..defaults},_=>unreachable!()};let result=store::decode_sqlite_snapshot_record_native(&payload,<En1994Snapshot as store::ArtifactDsl>::envelope_id(),En1994Snapshot::__dsl_spec_producer(),|record,native|crate::standards::v1::subsets::any::io::sqlite::snapshot::admission::admit(record,native,limits),&mut SqliteSnapshotControl::new(&mut |_|true,defaults));assert_eq!(result.is_ok(),accepted,"borrowed full CST before typed ownership {encoding:?} {role} {limits:?}");}}}
 source.retire_sqlite_snapshot();}
}
